var L=(typeof currentLang!=='undefined'&&currentLang==='es')?'es':'en';document.querySelectorAll('#article-section-seasonengine [data-se-en]').forEach(function(n){n.innerHTML=n.getAttribute('data-se-'+L);});
var el=document.getElementById('seAudience'); if(!el) return; var prev=Chart.getChart(el); if(prev) prev.destroy();
Chart.defaults.font.family="'DM Mono', monospace"; Chart.defaults.font.size=10; Chart.defaults.color='#6e6e78';
var G='rgba(255,255,255,0.05)'; var es=(L==='es'); function y(n){return es?(n+(n==='1'?' año':' años')).replace('.',','):n+'y';}
var rows=[['The Pitt S2 · ~'+y('1'),132],['Landman S2 · ~'+y('1'),52],['The Night Agent S3 · ~'+y('1'),-22],['Bridgerton S4 · '+y('1.75'),-20],['The Night Agent S2 · '+y('1.8'),-47],['Bridgerton S3 · '+y('2'),-7],['Rings of Power S2 · '+y('2'),-57],['Ginny & Georgia S3 · '+y('2.5'),-19],['Wednesday S2 · '+y('2.75'),-59],['Stranger Things S5 · '+y('3.5'),-23]];
new Chart(el,{type:'bar',data:{labels:rows.map(function(r){return r[0];}),datasets:[{data:rows.map(function(r){return r[1];}),
backgroundColor:rows.map(function(r){return r[1]>=0?'#34d399':'#f87171';}),borderRadius:3,barThickness:16}]},
options:{indexAxis:'y',responsive:true,maintainAspectRatio:false,
plugins:{legend:{display:false},tooltip:{backgroundColor:'#141419',borderColor:'#2a2a32',borderWidth:1,titleColor:'#e8e8ed',bodyColor:'#9898a2',padding:10,displayColors:false,
callbacks:{label:function(i){return (i.raw>0?'+':'')+i.raw+(es?'% vs. temporada anterior':'% vs prior season');}}}},
scales:{x:{min:-70,max:140,grid:{color:G,drawTicks:false},border:{display:false},ticks:{callback:function(v){return (v>0?'+':'')+v+'%';}}},
y:{grid:{display:false},border:{display:false},ticks:{color:'#9898a2'}}}}});

var L=(typeof currentLang!=='undefined'&&currentLang==='es')?'es':'en';document.querySelectorAll('#article-section-seasonengine [data-se-en]').forEach(function(n){n.innerHTML=n.getAttribute('data-se-'+L);});
var el=document.getElementById('seGapTrend'); if(!el) return; var prev=Chart.getChart(el); if(prev) prev.destroy();
Chart.defaults.font.family="'DM Mono', monospace"; Chart.defaults.font.size=10; Chart.defaults.color='#6e6e78';
var G='rgba(255,255,255,0.05)'; var es=(L==='es');
new Chart(el,{type:'line',data:{labels:['2016','2020','2021','2024','2025'],datasets:[{data:[10,12,16,21,21],borderColor:'#e8e8ed',borderWidth:2,tension:0.25,
pointBackgroundColor:'#c0392b',pointBorderColor:'#c0392b',pointRadius:3,fill:true,backgroundColor:'rgba(232,232,237,0.06)'}]},
options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false},tooltip:{backgroundColor:'#141419',borderColor:'#2a2a32',borderWidth:1,titleColor:'#e8e8ed',bodyColor:'#9898a2',padding:10,displayColors:false,
callbacks:{label:function(i){return i.raw+(es?' meses':' months');}}}},
scales:{x:{grid:{color:G,drawTicks:false},border:{display:false}},y:{min:0,max:24,grid:{color:G,drawTicks:false},border:{display:false},ticks:{stepSize:6,callback:function(v){return v+(es?' m':' mo');}}}}}});
